def mark_slow(items, base, prefix=""):
    """Add the ``slow`` marker to the collected items listed in ``SLOW``."""
    import pytest

    for item in items:
        try:
            relative = Path(item.path).resolve().relative_to(Path(base).resolve())
        except ValueError:
            continue
        if f"{prefix}{relative.as_posix()}::{item.name}" in SLOW:
            item.add_marker(pytest.mark.slow)
